"""The deliberately small, phone-first dashboard UI."""

INDEX_HTML = r"""<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#173b5b">
  <title>Raspberry Pi</title>
  <style>
    :root { color-scheme:light dark; --navy:light-dark(#173b5b,#a8c9e5); --blue:light-dark(#1269aa,#72c1f4); --ink:light-dark(#15232e,#edf5fb); --muted:light-dark(#5a6e7d,#afbfca); --bg:light-dark(#f3f7fa,#10191f); --card:light-dark(#fff,#18242c); --soft:light-dark(#e8f1f7,#20313b); --line:light-dark(#d4e0e7,#30414d); --good:light-dark(#167246,#6bd6a2); --warn:light-dark(#9b5b00,#f2c36c); --bad:light-dark(#b32e3a,#ff9aa2); }
    * { box-sizing:border-box; } body { margin:0; background:var(--bg); color:var(--ink); font:16px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; } button,input { font:inherit; } button,a { -webkit-tap-highlight-color:transparent; } button { cursor:pointer; } button:focus-visible,a:focus-visible,input:focus-visible { outline:3px solid color-mix(in srgb,var(--blue) 65%,transparent); outline-offset:2px; }
    .shell { width:min(760px,100%); min-height:100vh; margin:auto; padding:16px 16px calc(28px + env(safe-area-inset-bottom)); } .top { display:flex; align-items:center; justify-content:space-between; gap:12px; padding:4px 0 16px; } .brand { font-size:20px; font-weight:750; letter-spacing:-.025em; } .brand small { display:block; color:var(--muted); font-size:13px; font-weight:450; letter-spacing:0; } .refresh { min-width:44px; min-height:44px; border:1px solid var(--line); border-radius:10px; color:var(--ink); background:var(--card); font-size:19px; }
    nav { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:5px; padding:5px; border:1px solid var(--line); border-radius:12px; background:var(--soft); } nav button { min-width:0; min-height:42px; padding:0 1px; border:0; border-radius:8px; background:transparent; color:var(--muted); font-size:10px; font-weight:750; letter-spacing:0; white-space:nowrap; } nav button.active { background:var(--card); color:var(--navy); box-shadow:0 1px 2px #00142222; }
    main { padding-top:26px; } h1 { margin:0; font-size:clamp(27px,9vw,38px); line-height:1.08; letter-spacing:-.045em; } h2 { margin:0; font-size:20px; letter-spacing:-.02em; } h3,p { margin:0; } .eyebrow { margin-bottom:5px; color:var(--muted); font-size:13px; font-weight:650; } .lead { margin-top:9px; color:var(--muted); }
    .stack { display:grid; gap:12px; margin-top:20px; } .card { min-width:0; padding:17px; border:1px solid var(--line); border-radius:13px; background:var(--card); } .destination { display:grid; grid-template-columns:1fr auto; align-items:center; gap:12px; text-align:left; width:100%; min-height:92px; border:0; border-radius:13px; color:var(--ink); background:var(--card); padding:17px; box-shadow:0 1px 0 #0013220b; } .destination:hover { border-color:color-mix(in srgb,var(--blue) 45%,var(--line)); } .destination strong { display:block; font-size:18px; } .destination span { display:block; margin-top:3px; color:var(--muted); font-size:14px; } .arrow { color:var(--blue); font-size:26px; }
    .status { display:inline-flex; align-items:center; gap:7px; color:var(--muted); font-size:14px; } .dot { width:9px; height:9px; flex:0 0 auto; border-radius:50%; background:var(--warn); } .dot.good { background:var(--good); } .dot.bad { background:var(--bad); } .notice { margin-top:16px; padding:13px 14px; border:1px solid var(--line); border-left:4px solid var(--warn); border-radius:9px; color:var(--ink); background:var(--card); } .notice.error { border-left-color:var(--bad); }
    .page-head { display:flex; align-items:start; justify-content:space-between; gap:12px; margin-bottom:16px; } .back { min-height:42px; min-width:72px; border:1px solid var(--line); border-radius:9px; color:var(--ink); background:var(--card); font-weight:650; } .back:disabled { opacity:.45; cursor:default; }
    .path { overflow:hidden; color:var(--muted); text-overflow:ellipsis; white-space:nowrap; font-size:14px; } .list { margin:0; padding:0; list-style:none; } .entry { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:10px; align-items:center; padding:13px 0; border-bottom:1px solid var(--line); } .entry:last-child { border-bottom:0; } .entry button,.entry a { min-width:0; padding:0; border:0; color:var(--ink); background:transparent; font-weight:680; text-align:left; text-decoration:none; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; } .entry button:hover,.entry a:hover { color:var(--blue); } .entry small { display:block; margin-top:3px; color:var(--muted); font-size:13px; font-weight:400; } .download { padding:9px 10px !important; border:1px solid var(--line) !important; border-radius:8px !important; color:var(--blue) !important; font-size:14px; white-space:nowrap; } .empty { padding:28px 8px; color:var(--muted); text-align:center; } .more { width:100%; min-height:45px; margin-top:12px; border:1px solid var(--line); border-radius:9px; color:var(--blue); background:var(--card); font-weight:700; }
    .video-wrap { overflow:hidden; margin-top:16px; border-radius:12px; background:#071015; aspect-ratio:4/3; } video { display:block; width:100%; height:100%; background:#071015; object-fit:contain; } .actions { display:flex; gap:9px; flex-wrap:wrap; margin-top:13px; } .action { min-height:44px; padding:9px 13px; border:1px solid var(--line); border-radius:9px; color:var(--ink); background:var(--card); font-weight:680; } .action.primary { border-color:var(--blue); color:#fff; background:var(--blue); }
    dl { display:grid; grid-template-columns:minmax(112px,.65fr) minmax(0,1.35fr); gap:11px 14px; margin:2px 0 0; font-size:15px; } dt { color:var(--muted); } dd { margin:0; overflow-wrap:anywhere; } .login { max-width:410px; margin:12vh auto; } label { display:grid; gap:7px; margin:17px 0; color:var(--muted); font-size:14px; } input { min-height:47px; border:1px solid var(--line); border-radius:9px; padding:9px 11px; color:var(--ink); background:var(--card); } .login .action { width:100%; }
    @media (max-width:380px) { .shell { padding-left:12px; padding-right:12px; } nav button { font-size:10px; } .card,.destination { padding:14px; } }
  </style>
</head>
<body>
  <div class="shell">
    <header class="top"><div class="brand">Raspberry Pi<small>Private access over Tailscale</small></div><button class="refresh" onclick="refresh()" aria-label="Refresh">↻</button></header>
    <nav aria-label="Main navigation"><button data-page="home" onclick="go('home')">HOME</button><button data-page="files" onclick="go('files')">FILES</button><button data-page="camera" onclick="go('camera')">CAMERA</button><button data-page="system" onclick="go('system')">SYSTEM</button></nav>
    <main id="app" aria-live="polite">Loading…</main>
  </div>
  <script>
    const app=document.getElementById('app');
    const state={page:'home',status:{},storage:{},camera:{},files:null,path:'',cursor:null,loading:false};
    const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const js=v=>JSON.stringify(v).replace(/&/g,'&amp;').replace(/</g,'\\u003c').replace(/"/g,'&quot;');
    const bytes=v=>{if(typeof v!=='number')return '—';const u=['B','KB','MB','GB','TB'];let n=v,i=0;while(n>=1024&&i<u.length-1){n/=1024;i++;}return `${n.toFixed(i<2?0:1)} ${u[i]}`;};
    const time=v=>{if(!v)return 'Not reported';const d=new Date(typeof v==='number'?v*1000:v);return Number.isNaN(d)?String(v):new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(d);};
    const dot=good=>`<span class="dot ${good?'good':'bad'}"></span>`;
    async function api(path,options={}) { const r=await fetch(path,{...options,credentials:'same-origin'}); if(!r.ok){let detail=await r.text();try{detail=JSON.parse(detail).detail||detail;}catch{}const e=new Error(detail||`Request failed (${r.status})`);e.status=r.status;throw e;} return (r.headers.get('content-type')||'').includes('application/json')?r.json():r; }
    async function establishSession(token){ await api('/api/session',{method:'POST',headers:{'X-Workspace-Token':token}}); }
    function login(message='Enter the dashboard token to continue.'){ app.innerHTML=`<section class="login card"><p class="eyebrow">PRIVATE DASHBOARD</p><h1>Connect</h1><p class="lead">${esc(message)}</p><label>Dashboard token<input id="token" type="password" autocomplete="current-password" autofocus></label><button class="action primary" onclick="submitLogin()">Connect</button></section>`; }
    async function submitLogin(){const input=document.getElementById('token');try{await establishSession(input.value);await refresh();}catch(e){login(e.message);}}
    async function refresh(){ try { const [storage,camera]=await Promise.all([api('/api/storage/status'),api('/api/camera/live/status')]); state.storage=storage;state.camera=camera; if(state.page==='files')await loadFiles(); else render(); api('/api/status').then(status=>{state.status=status;if(state.page!=='files')render();}).catch(()=>{}); } catch(e) { if(e.status===401)login(); else app.innerHTML=`<div class="notice error"><strong>Unable to reach the Pi.</strong><br>${esc(e.message)}</div>`; } }
    function go(page){state.page=page;history.replaceState(null,'',`#${page}`);if(page==='files'){state.path='';state.cursor=null;loadFiles();}else render();}
    function setNav(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));}
    function render(){setNav();if(state.page==='home')return home();if(state.page==='files')return files();if(state.page==='camera')return camera();system();}
    function home(){const storageOk=!!state.storage.mounted, camOk=!!state.camera.available;app.innerHTML=`<p class="eyebrow">HOME</p><h1>Raspberry Pi</h1><p class="lead">Your private files and live camera.</p><section class="stack"><button class="destination" onclick="go('files')"><span><strong>Files</strong><span>${storageOk?'Browse the attached storage':'Storage drive unavailable'}</span></span><b class="arrow">›</b></button><button class="destination" onclick="go('camera')"><span><strong>Camera</strong><span>${camOk?'Live camera':'Camera reconnecting'}</span></span><b class="arrow">›</b></button><button class="destination" onclick="go('system')"><span><strong>System</strong><span>Pi, storage, and camera status</span></span><b class="arrow">›</b></button></section><div class="notice"><span class="status">${dot(storageOk)} ${esc(state.storage.detail||'Storage status unknown')}</span><br><span class="status">${dot(camOk)} ${esc(state.camera.detail||'Camera status unknown')}</span></div>`;}
    async function loadFiles(append=false){state.loading=true;render();try{const q=new URLSearchParams({path:state.path,limit:'120'});if(append&&state.cursor)q.set('cursor',state.cursor);const result=await api(`/api/storage/list?${q}`);if(append&&state.files)result.entries=[...state.files.entries,...result.entries];state.files=result;state.cursor=result.next_cursor||null;}catch(e){state.files={error:e.message,entries:[]};state.cursor=null;}finally{state.loading=false;render();}}
    function files(){setNav();const s=state.storage;if(!s.mounted){app.innerHTML=`<section class="page-head"><div><p class="eyebrow">FILES</p><h1>Files</h1></div></section><div class="notice error"><strong>Storage unavailable</strong><br>${esc(s.detail||'The storage drive is not currently mounted.')}</div>`;return;}const f=state.files||{entries:[]},crumb=state.path?state.path:'Attached storage';const parent=state.path.includes('/')?state.path.slice(0,state.path.lastIndexOf('/')):'';app.innerHTML=`<section class="page-head"><div><p class="eyebrow">FILES</p><h1>Files</h1><p class="path" title="${esc(crumb)}">${esc(crumb)}</p></div><button class="back" ${state.path?'':'disabled'} onclick="openFolder(${js(parent)})">Back</button></section>${state.loading?'<p class="empty">Reading files…</p>':f.error?`<div class="notice error"><strong>Could not read this folder.</strong><br>${esc(f.error)}</div>`:f.entries.length?`<ul class="list">${f.entries.map(e=>`<li class="entry"><div>${e.is_dir?`<button title="${esc(e.name)}" onclick="openFolder(${js(e.path)})">📁 ${esc(e.name)}<small>Folder · ${esc(time(e.modified))}</small></button>`:`<a title="${esc(e.name)}" href="/api/storage/download?path=${encodeURIComponent(e.path)}">${esc(e.name)}<small>${esc(e.type||'File')} · ${bytes(e.size_bytes)} · ${esc(time(e.modified))}</small></a>`}</div>${e.is_dir?'':`<a class="download" href="/api/storage/download?path=${encodeURIComponent(e.path)}" aria-label="Download ${esc(e.name)}">Download</a>`}</li>`).join('')}</ul>`:'<p class="empty">This folder is empty.</p>'}${state.cursor?'<button class="more" onclick="loadFiles(true)">Show more files</button>':''}`;}
    function openFolder(path){state.path=path;state.cursor=null;state.files=null;loadFiles();}
    function camera(){setNav();const c=state.camera;if(!c.available){app.innerHTML=`<section class="page-head"><div><p class="eyebrow">CAMERA</p><h1>Camera</h1></div><span class="status">${dot(false)} Offline</span></section><div class="notice error"><strong>Camera unavailable</strong><br>${esc(c.detail||'The camera is currently offline. Retrying automatically.')}</div><div class="actions"><button class="action" onclick="refreshCamera()">Refresh stream</button></div>`;return;}const src=`/api/camera/live/index.m3u8?v=${Date.now()}`;app.innerHTML=`<section class="page-head"><div><p class="eyebrow">CAMERA</p><h1>Camera</h1></div><span class="status">${dot(true)} LIVE</span></section><div class="video-wrap"><video id="live-video" controls autoplay muted playsinline preload="auto"><source src="${src}" type="application/vnd.apple.mpegurl"></video></div><div class="actions"><button class="action primary" onclick="fullScreen()">Fullscreen</button><button class="action" onclick="refreshCamera()">Refresh stream</button></div><p class="lead">${esc(c.width)} × ${esc(c.height)} · ${esc(c.fps)} fps · private HLS stream</p>`;const video=document.getElementById('live-video');video.play().catch(()=>{});}
    async function refreshCamera(){try{state.camera=await api('/api/camera/live/status');render();}catch(e){app.innerHTML=`<div class="notice error">${esc(e.message)}</div>`;}}
    function fullScreen(){const v=document.getElementById('live-video');if(v?.requestFullscreen)v.requestFullscreen();else if(v?.webkitEnterFullscreen)v.webkitEnterFullscreen();}
    function system(){setNav();const s=state.status||{},storage=state.storage||{},cam=state.camera||{};app.innerHTML=`<section class="page-head"><div><p class="eyebrow">SYSTEM</p><h1>System</h1></div><span class="status">${dot(String(s.overall||'').toLowerCase()!=='error')} ${esc(s.overall||'Checking')}</span></section><section class="card"><dl><dt>Pi</dt><dd>${esc(s.overall||'Status unavailable')}</dd><dt>Storage</dt><dd>${storage.mounted?'Mounted · '+bytes(storage.available_bytes)+' free':'Unavailable'}</dd><dt>Camera</dt><dd>${cam.available?'Live · '+cam.width+' × '+cam.height+' at '+cam.fps+' fps':'Offline / reconnecting'}</dd><dt>Backup</dt><dd>${esc(s.backup?.state||s.backup?.last||'Status not reported')}</dd></dl></section><div class="notice"><strong>Private access only</strong><br>This dashboard is available through your Tailscale network.</div>`;}
    const initial=location.hash.slice(1);if(['home','files','camera','system'].includes(initial))state.page=initial;refresh();
  </script>
</body>
</html>"""
